WITH deduped AS (SELECT * FROM order_items QUALIFY ROW_NUMBER() OVER (PARTITION BY product_id, order_id ORDER BY quantity DESC NULLS FIRST, id) = 1) SELECT order_id, CASE WHEN quantity >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, ROUND(AVG(quantity), 2) AS avg_quantity, PERCENTILE_APPROX(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, COUNT(*) AS num_rows FROM deduped GROUP BY 1, 2 HAVING num_rows > 1 ORDER BY order_id;
